 * its map position (source-kt66, source-c573).  Declared in fim/fim.h.
 *
 * One byte per address space (FIM_AS_COUNT = 58, fim/fim.h); bit 7 is "a
 * trace fault is pending for this address space".  FIM_$DELIVER_TRACE_FAULT
 * sets it (`bset.b #7'), FIM_$CLEAR_TRACE_FAULT and the trace arm of
 * FIM_$EXIT clear it (`bclr.b #7'); the transitions that change it also
 * step PENDING_TRACE_FAULTS and, at the zero boundary, patch FIM_$EXIT's
 * first word between rte and nop.  Those three routines, and
 * FIM_$SPURIOUS_INT, load this address as their module base
 * (`lea (d16,PC),An' = 0x00E21890); see each for how its other cells are
 * reached.
 *
 * The image holds 58 zero bytes here.  The section is longword aligned, as
 * the segment is in the image (0x00E21890), so that JMP_TO_BUS_ERR, the
 * next section (fim/sau2/bus_err.s), starts two bytes off a longword and
 * its operand cell BUS_ERROR_SWITCH is longword aligned, as at 0x00E218CC.
 */

        .section ".text.FIM_$TRACE_BIT","ax",@progbits
        .balign 4

        .equ    FIM_AS_COUNT, 58        /* fim/fim.h */

        .global FIM_$TRACE_BIT
